input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop" {
            webStore = container "Web Store" "The web application where customers browse and buy books" "Java"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Java"

            customer -> webStore "Places orders through" "HTTPS"
            webStore -> orderProcessor "Submits orders to" "gRPC"
        }
    }

    views {
        systemContext bookshop "SystemContext" "Shows the Bookshop system and its relationship with the Customer" {
            include *
            autoLayout
        }
    }
}

